toolUseResult.originalFile:
scheme: mh.ladki_bahin
# Base person used by every case: an eligible woman under the 2024-06-28 GR.
# Each case changes only what it tests. Every case cites its clause.
base: &base
  age: 35
  gender: female
  state: MH
  marital_status: married
  annual_family_income: 180000
  has_bank_account: true

cases:
  - name: typical eligible woman gets Rs 1,500
    date: 2024-06-30
    person: {<<: *base}
    expect: {eligible: true, monthly_inr: 1500}
    source: GR 202406281814018230 p.2 para 2 and 4

  - name: scheme not in force before launch
    date: 2024-06-27
    person: {<<: *base}
    expect: {eligible: false, in_force: false}
    source: GR 202406281814018230 dated 2024-06-28

  - name: age 21 is eligible (lower boundary)
    date: 2024-06-30
    person: {<<: *base, age: 21}
    expect: {eligible: true}
    source: GR 202406281814018230 p.2 clause 4(3)

  - name: age 20 is not eligible
    date: 2024-06-30
    person: {<<: *base, age: 20}
    expect: {eligible: false}
    source: GR 202406281814018230 p.2 clause 4(3)

  - name: age 60 is eligible (upper boundary)
    date: 2024-06-30
    person: {<<: *base, age: 60}
    expect: {eligible: true}
    source: GR 202406281814018230 p.2 clause 4(3)

  - name: age 61 is not eligible
    date: 2024-06-30
    person: {<<: *base, age: 61}
    expect: {eligible: false}
    source: GR 202406281814018230 p.2 clause 4(3)

  - name: income exactly Rs 2.5 lakh is eligible
    date: 2024-06-30
    person: {<<: *base, annual_family_income: 250000}
    expect: {eligible: true}
    source: GR 202406281814018230 p.2 clause 4(5) "not more than"

  - name: income Rs 2,50,001 is not eligible
    date: 2024-06-30
    person: {<<: *base, annual_family_income: 250001}
    expect: {eligible: false}
    source: GR 202406281814018230 p.2 clause 5(1)

  - name: men are not eligible
    date: 2024-06-30
    person: {<<: *base, gender: male}
    expect: {eligible: false}
    source: GR 202406281814018230 p.2 clause 3

  - name: resident of another state is not eligible
    date: 2024-06-30
    person: {<<: *base, state: other}
    expect: {eligible: false}
    source: GR 202406281814018230 p.2 clause 4(1)

  - name: widow is eligible
    date: 2024-06-30
    person: {<<: *base, marital_status: widowed}
    expect: {eligible: true}
    source: GR 202406281814018230 p.2 clause 4(2)

  - name: unmarried woman is not eligible under the original GR
    date: 2024-06-30
    person: {<<: *base, marital_status: unmarried}
    expect: {eligible: false}
    source: GR 202406281814018230 p.2 clause 4(2)

  - name: no bank account is not eligible
    date: 2024-06-30
    person: {<<: *base, has_bank_account: false}
    expect: {eligible: false}
    source: GR 202406281814018230 p.2 clause 4(4)

  - name: income tax payer in family is not eligible
    date: 2024-06-30
    person: {<<: *base, family_income_tax_payer: true}
    expect: {eligible: false}
    source: GR 202406281814018230 p.2 clause 5(2)

  - name: contract government employee in family is not eligible
    date: 2024-06-30
    person: {<<: *base, family_govt_job: contract}
    expect: {eligible: false}
    source: GR 202406281814018230 p.2 clause 5(3)

  - name: outsourced worker in family is eligible
    date: 2024-06-30
    person: {<<: *base, family_govt_job: outsourced}
    expect: {eligible: true}
    source: GR 202406281814018230 p.2 clause 5(3) proviso

  - name: pensioner in family is not eligible
    date: 2024-06-30
    person: {<<: *base, family_govt_job: pensioner}
    expect: {eligible: false}
    source: GR 202406281814018230 p.2 clause 5(3)

  - name: receives exactly Rs 1,500 from another scheme, eligible but paid nothing extra
    date: 2024-06-30
    person: {<<: *base, other_scheme_monthly_inr: 1500}
    expect: {eligible: true, monthly_inr: 0}
    source: GR 202406281814018230 p.2 clause 5(4) "more than" and para 2

  - name: receives Rs 1,501 from another scheme is not eligible
    date: 2024-06-30
    person: {<<: *base, other_scheme_monthly_inr: 1501}
    expect: {eligible: false}
    source: GR 202406281814018230 p.2 clause 5(4)

  - name: receives Rs 1,000 from another scheme gets the Rs 500 difference
    date: 2024-06-30
    person: {<<: *base, other_scheme_monthly_inr: 1000}
    expect: {eligible: true, monthly_inr: 500}
    source: GR 202406281814018230 p.2 para 2

  - name: MP or MLA in family is not eligible
    date: 2024-06-30
    person: {<<: *base, family_mp_mla: true}
    expect: {eligible: false}
    source: GR 202406281814018230 p.2 clause 5(5)

  - name: government board member in family is not eligible
    date: 2024-06-30
    person: {<<: *base, family_govt_board_office: true}
    expect: {eligible: false}
    source: GR 202406281814018230 p.2 clause 5(6)

  - name: exactly 5 acres of farm land is eligible
    date: 2024-06-30
    person: {<<: *base, family_farm_land_acres: 5}
    expect: {eligible: true}
    source: GR 202406281814018230 p.2 clause 5(7) "more than five acres"

  - name: 5.5 acres of farm land is not eligible
    date: 2024-06-30
    person: {<<: *base, family_farm_land_acres: 5.5}
    expect: {eligible: false}
    source: GR 202406281814018230 p.2 clause 5(7)

  - name: four-wheeler in family is not eligible
    date: 2024-06-30
    person: {<<: *base, family_four_wheeler: true}
    expect: {eligible: false}
    source: GR 202406281814018230 p.2 clause 5(8)
